create table profiles(id uuid primary key references auth.users on delete cascade, name text not null check(char_length(name) between 2 and 20), bio text default '', city text default '', created_at timestamptz default now());
create table rooms(id serial primary key, name text not null, tag text);
create table messages(id bigserial primary key, room_id int references rooms on delete cascade, to_user uuid references profiles on delete cascade, sender uuid not null default auth.uid() references profiles on delete cascade, content text not null check(char_length(content) between 1 and 500), created_at timestamptz default now(), check((room_id is null) <> (to_user is null)));
create table blocks(blocker uuid default auth.uid() references profiles on delete cascade, blocked uuid references profiles on delete cascade, primary key(blocker,blocked));
create table reports(id bigserial primary key, reporter uuid default auth.uid(), target text not null, created_at timestamptz default now());
alter table profiles enable row level security;
alter table rooms enable row level security;
alter table messages enable row level security;
alter table blocks enable row level security;
alter table reports enable row level security;
create policy "p_read" on profiles for select to authenticated using (true);
create policy "p_ins" on profiles for insert to authenticated with check (id = auth.uid());
create policy "p_upd" on profiles for update to authenticated using (id = auth.uid());
create policy "r_read" on rooms for select to authenticated using (true);
create policy "m_read" on messages for select to authenticated using (room_id is not null or sender = auth.uid() or to_user = auth.uid());
create policy "m_ins" on messages for insert to authenticated with check (sender = auth.uid());
create policy "b_all" on blocks for all to authenticated using (blocker = auth.uid()) with check (blocker = auth.uid());
create policy "x_ins" on reports for insert to authenticated with check (reporter = auth.uid());
insert into rooms(name,tag) values ('قهوة الصباح','يمني'),('دردشة مصرية','مصري'),('مجلس شامي','شامي'),('سهرة مغربية','مغربي'),('ديوان عراقي','عراقي');
alter publication supabase_realtime add table messages;
create function delete_me() returns void language sql security definer set search_path = public as $$ delete from auth.users where id = auth.uid() $$;
revoke execute on function delete_me() from public, anon;
grant execute on function delete_me() to authenticated;
